{
  "id": "V012",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "지역별 생활 장면에 맞는 광고 이미지 후보 준비 목적이 보존됩니다."
    },
    {
      "field": "action",
      "score": 1,
      "reason": "후보를 검토·승인하고 게시하는 절차는 있지만, 배경 장면을 달리한 후보를 만드는 행동은 명시되지 않습니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "제품 사진과 광고 이미지 후보가 포함됩니다."
    },
    {
      "field": "input",
      "score": 1,
      "reason": "승인된 제품 사진은 보존되지만, 지역별 생활 장면을 배경으로 활용한다는 입력 조건은 충분히 드러나지 않습니다."
    },
    {
      "field": "output",
      "score": 1,
      "reason": "이미지 후보는 언급되지만, 배경을 달리한 초안이라는 출력 특성은 빠져 있습니다."
    },
    {
      "field": "constraints",
      "score": 1,
      "reason": "제품 외형·브랜드 표현 유지와 승인 후 게시 조건은 보존되지만, 성능 변경 및 새 효능 문구 추가 금지는 빠져 있습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "출처에 없는 기능을 추가했다고 볼 근거가 없습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "담당자의 검토와 승인이 명시되고, AI가 게시하거나 승인한다고 하지 않습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "제품 성능을 바꾸거나 새 효능 문구를 추가하지 않으며",
      "view_quote": "",
      "reason": "제품 성능 변경과 새 효능 문구 추가 금지가 모든 뷰에서 누락되었습니다."
    },
    {
      "type": "OMISSION",
      "source_quote": "배경 장면을 달리한 이미지 후보를 만들어",
      "view_quote": "",
      "reason": "배경 장면을 달리해 이미지 후보를 만드는 행동이 모든 뷰에서 누락되었습니다."
    }
  ],
  "permission_interpretation": "실제 광고 게시는 담당자의 승인 뒤에 진행됩니다. 뷰는 AI가 게시하거나 승인한다고 주장하지 않습니다."
}
